\begin{proposition}[线性化算子的谱分解]\label{thm:form-splitting-stage5}
存在 $e_0,c_0,C_0>0$、有界投影 $P_h,P_0,P_c$ 与固定有限秩可逆变换
$\mathbb T_0$，使
\begin{equation*}
 \mathcal X_1=E_h\dotplus E_0\dotplus E_c,
 \qquad
 E_h=\operatorname{span}\{\mathcal Y_+,\mathcal Y_-\},
 \qquad
 E_0=\operatorname{span}\left\{
 \binom{\Lambda W}{0},\binom0W\right\},
\end{equation*}
并满足：
\begin{enumerate}[label=\textup{(S\arabic*)}]
 \item $\mathbb A_0\mathcal Y_\pm=\pm e_0\mathcal Y_\pm$，且这是唯一非零径向实特征对；
 \item 在 $E_c$ 上
 \begin{equation}\label{eq:coercive-Ec-stage2}
 c_0\|Z\|_{\mathcal X_1}^2
 \le\langle\mathbb L_0Z,Z\rangle
 \le C_0\|Z\|_{\mathcal X_1}^2;
 \end{equation}
 \item $\mathbb T_0^{-1}\mathbb A_0\mathbb T_0$ 相对于
 $E_h\dotplus E_0\dotplus E_c$ 精确约化；并且
 \begin{equation*}
 \|P_h\|_{\mathfrak B_{\rm f}}
 +\|P_0\|_{\mathfrak B_{\rm f}}
 +\|P_c\|_{\mathfrak B_{\rm f}}
 +\|\mathbb T_0^{\pm1}\|_{\mathfrak B_{\rm f}}
 \le C_0.
 \end{equation*}
\end{enumerate}
\end{proposition}

\begin{proposition}[参数依赖的线性化分解]\label{thm:slow-Feshbach-stage3}
存在 $\varepsilon_{\rm sl}>0$，使当
$\sup_s\|\mathbb K_{\rm sl}(s)\|_{\mathfrak B_{\rm f}}\le\varepsilon_{\rm sl}$ 时，存在 $C^1$ 可逆族
\begin{equation*}
 \mathbb T_{\rm sl}(s)=\mathbb T_0\mathbb S_{\rm sl}(s)
\end{equation*}
满足
\begin{align}
 \|\mathbb S_{\rm sl}^{\pm1}-I\|_{\mathfrak B_{\rm f}}
 &\le C\|\mathbb K_{\rm sl}\|_{\mathfrak B_{\rm f}},\notag \\
 \|\partial_s\mathbb S_{\rm sl}^{\pm1}\|_{\mathfrak B_{\rm f}}
 &\le C\|\partial_s\mathbb K_{\rm sl}\|_{\mathfrak B_{\rm f}},
 \label{eq:Ssl-der-stage3}
\end{align}
并精确块对角化静态慢生成元：
\begin{equation}\label{eq:slow-block-stage3}
 \mathbb T_{\rm sl}^{-1}\mathbb A_{\rm sl}\mathbb T_{\rm sl}
 =\mathbb H_h^{\rm sl}\oplus\mathbb M_0^{\rm sl}\oplus\mathbb A_c^{\rm sl}.
\end{equation}
双曲块保持指数隙，补空间保持一致 coercivity；完整移动生成元中新增的非对角项满足
\begin{equation}\label{eq:Esl-L1-stage3}
 \int_{s_0}^\infty\|\mathbb E_{\rm sl}(s)\|_{\mathfrak B_{\rm f}}\,\dd s
 \le C\int_{s_0}^\infty
 \bigl(\|\partial_s\mathbb K_{\rm sl}\|
 +s^{-1}\|\mathbb K_{\rm sl}\|
 +\|\mathbb R_{\rm int}\|\bigr)\,\dd s<\infty.
\end{equation}
\end{proposition}

\begin{lemma}[慢标架连接的点态可积裕量]\label{lem:Esl-pointwise-v2}
对命题~\ref{thm:finite-profile-stage3} 的有限背景，存在
$\kappa_{\rm sl}>0$，使充分大的 $s_0$ 上
\begin{equation*}
 \|\mathbb E_{\rm sl}(s)\|_{\mathfrak B_{\rm f}}
 \le C s^{-1-\kappa_{\rm sl}}.
\end{equation*}
同样的估计对固定 $g$ 的两条 $h$ 路径之差成立，并多乘其
$\mathcal P_\delta$ 距离。
\end{lemma}

\begin{proposition}[一般终端辐射下的调制方程]\label{thm:full-slow-modulation-v2}
令 $V_N[h;g]$ 为命题~\ref{thm:finite-profile-stage3} 的动态剖面，
$\mathbb T_{\rm sl}$ 为命题~\ref{thm:slow-Feshbach-stage3} 的完整慢变换，并写
\[
 \widehat Z:=\mathbb T_{\rm sl}^{-1}\operatorname{vec}(v-V_N[h;g]).
\]
施加动态阈值正交 $P_0\widehat Z=0$。则在紧参数图和小终端辐射球上一致存在
$2\times2$ 矩阵 $\widehat{\mathcal M}_N(s)$，满足
\begin{equation}\label{eq:Mhat-v2}
 \|\widehat{\mathcal M}_N-I_2\|\le\frac14,
 \qquad
 \|\widehat{\mathcal M}_N^{-1}\|\le\frac43,
\end{equation}
且物理 Kummer 参数满足
\begin{equation*}
 \widehat{\mathcal M}_N(s)\,\zeta_s=\mathcal F_N^{\rm mod}(s),
\end{equation*}
其中
\begin{equation}\label{eq:full-mod-bound-v2}
 |\mathcal F_N^{\rm mod}(s)|
 \le C\left[
 s^{-N}+s^{-1-\kappa_{\rm sl}}
 +s^{-1}\|\widehat Z(s)\|_{\mathcal X_1}
 +s^{-1-\kappa_{\rm sl}}\|\widehat Z(s)\|_{\mathcal X_{\rm f}}
 +\|\widehat Z(s)\|_{\mathcal X_{\rm f}}^2
 \right].
\end{equation}
特别地，一般 $g\ne0$ 的所有不可积 $A_g,A_g^2,A_g^3,A_gc_g,\ldots$
慢 Hessian 项均只进入精确块对角主部，不在调制右端留下裸的长程线性漂移。
\end{proposition}

\begin{lemma}[单条轨道的后向线性估计]\label{prop:single-green-stage4}
取 $M>\mu_*+3$，并令 $s_0$ 足够大。对方程~\eqref{eq:exact-error-stage4} 的任意源项 $F$，存在唯一终端规范化后向解算子 $\mathbb G_{h,g}$；稳定双曲方向还存在齐次传播 $\mathbb S_{h,g}[\alpha_-]$。它们满足
\begin{align}
 \|\mathbb G_{h,g}F\|_{\mathcal X_M}
 &\le C_M\|F\|_{\mathcal Y_{M+1}},
 \label{eq:single-Green-stage4}\\
 \|\mathbb G_{h,g}F\|_{\mathcal X_{M+\ell}}
 &\le C_{M,\ell}\|F\|_{\mathcal Y_{M+1+\ell}},\notag \\
 \|\mathbb S_{h,g}[\alpha_-]\|_{\mathcal X_M}
 &\le C_Ms_0^M|\alpha_-|.\notag \end{align}
\end{lemma}

\begin{proposition}[两条轨道的后向比较]\label{prop:lossy-green-stage4}
设 $F,\widetilde F$ 分别位于两条路径的源纤维，且
$\widetilde F\in\mathcal Y_{M+1+\ell_{\rm lr}}$。则
\begin{align}
 &\left\|\mathbb G_{h,g}F
 -\mathbf C^Z_{h\leftarrow\widetilde h}
 \mathbb G_{\widetilde h,\widetilde g}\widetilde F\right\|_{\mathcal X_M}
 \notag\\
 &\quad\le C_M
 \left\|F-\mathbf C^F_{h\leftarrow\widetilde h}\widetilde F\right\|_{\mathcal Z_M}
 +C_Ms_0^{-\eta}(d_h+d_g)
 \|\widetilde F\|_{\mathcal Y_{M+1+\ell_{\rm lr}}}.
 \label{eq:lossy-Green-stage4}
\end{align}
特别地，若 $F=\mathbf C^F_{h\leftarrow\widetilde h}\widetilde F$，则
\begin{equation}\label{eq:lossy-Green-simple-stage4}
 \left\|\mathbb G_{h,g}F
 -\mathbf C^Z_{h\leftarrow\widetilde h}
 \mathbb G_{\widetilde h,\widetilde g}\widetilde F\right\|_{\mathcal X_M}
 \le C_Ms_0^{-\eta}(d_h+d_g)
 \|\widetilde F\|_{\mathcal Y_{M+1+\ell_{\rm lr}}}.
\end{equation}
\end{proposition}

\begin{proposition}[参数与余项的联合构造]\label{thm:joint-contraction-stage4}
按 \eqref{eq:rho-lr-v4}、\eqref{eq:delta-choice-stage4} 选择
$\delta,\ell_{\rm lr},M,N$。存在 $\varepsilon_*>0$ 与 $s_*>0$，使只要
\begin{equation*}
 \|g\|_{\mathcal R_N}\le\varepsilon_*,
 \qquad |\alpha_-|\le s_0^{1-N},
 \qquad s_0\ge s_*,
\end{equation*}
则
$\widehat{\mathcal T}=(\widehat{\mathcal T}_\zeta,
\widehat{\mathcal T}_Q)$ 把
$\widehat{\mathbb B}_{s_0}$ 映入自身，并在普通和范数下严格压缩。因此存在唯一固定点
\begin{equation}\label{eq:fixed-point-stage4}
 (h_*,\widehat Q_*)
 =\widehat{\mathcal T}(h_*,\widehat Q_*).
\end{equation}
恢复原路径纤维误差
\begin{equation}\label{eq:recover-Q-v4}
 Q_*:=(\mathbf U_{h_*}^Z)^{-1}\widehat Q_*.
\end{equation}
增长双曲起始坐标由引理~\ref{prop:shooting-stage4} 唯一给出
\begin{equation*}
 \alpha_+=\Gamma_{s_0}(\zeta_\infty,g,\alpha_-).
\end{equation*}
\end{proposition}

\begin{proposition}[初值图与速率函数的 $C^1$ 性]\label{prop:center-stable-C1-v52}
对每个固定 $s_0\ge s_*$，射击坐标满足
\begin{equation*}
 \alpha_+=\Gamma_{s_0}(\zeta_\infty,g,\alpha_-),
 \qquad \Gamma_{s_0}\in C^1,
\end{equation*}
并在
\begin{equation*}
 (\zeta_\infty,g,\alpha_-,\alpha_+)
 \in\mathbb R^2\times\mathcal R_N\times\mathbb R^2,
 \qquad |\alpha_-|\le s_0^{1-N},
\end{equation*}
中定义余维一局部 $C^1$ 图。端点映射
\begin{equation*}
 \mathfrak E_{s_0}(\zeta_\infty,g,\alpha_-)
 :=\zeta(s_0)=\zeta_\infty+h_*(s_0)
\end{equation*}
满足
\begin{equation*}
 D_{\zeta_\infty}\mathfrak E_{s_0}=I_2+O(s_0^{-\delta}),
\end{equation*}
故充分大的 $s_0$ 上关于 $\zeta_\infty$ 局部可逆，并且
\begin{equation}\label{eq:rate-map-stage4}
 a_\infty(u_0):=2\mu_\infty(u_0)+\frac12
\end{equation}
是在该图上的局部 $C^1$ 函数。
\end{proposition}

